class Solution {
public:
    string clearDigits(string s) {
        int j = 0;
        for (char c : s) {
            if (c >= '0' && c <= '9') {
                if (j > 0) j--;
            } else {
                s[j++] = c;
            }
        }
        s.resize(j);
        return s;
    }
};
